package org.sleepwell.app;

import android.app.*;
import android.content.*;
import android.os.Bundle;
import android.text.InputType;
import android.view.*;
import android.widget.*;
import java.time.*;
import java.time.format.DateTimeFormatter;
import java.util.*;
import java.util.concurrent.*;
import java.util.function.LongConsumer;

/** Native record editor. All changes stay in a draft until the single atomic Save. */
public final class RecordEditorActivity extends Activity {
    private final ExecutorService worker=Executors.newSingleThreadExecutor();
    private final android.os.Handler handler=new android.os.Handler(android.os.Looper.getMainLooper());private String createToken,saveToken;private boolean resumed;
    private long id,expectedUpdated;private RecordEntry record;private RecordDraft draft;private ZoneId zone;private Bundle pending;private boolean saving;private String failure="";
    private EditText note;private TextView duration,startValue,endValue,error,date;private LinearLayout tags,awake;private PeriodTimeline timeline;private Button save;
    @Override public void onCreate(Bundle state){super.onCreate(state);RecordUi.review(this);if(android.os.Build.VERSION.SDK_INT>=33)getOnBackInvokedDispatcher().registerOnBackInvokedCallback(android.window.OnBackInvokedDispatcher.PRIORITY_DEFAULT,this::finish);id=getIntent().getLongExtra("record",0);zone=ZoneId.systemDefault();pending=state;createToken=state==null?UUID.randomUUID().toString():state.getString("createToken",UUID.randomUUID().toString());saveToken=state==null?null:state.getString("saveToken");saving=saveToken!=null;loading();if(id==0){long end=System.currentTimeMillis()/60000*60000;draft=new RecordDraft(end-Math.max(1,SleepPlans.load(this).goal)*60000L,end);restoreDraft();render();}else load();}
    private void loading(){LinearLayout body=Design.page(this,false,null,n->{});RecordUi.header(body,id==0?"Add sleep":"Edit sleep",this::finish);Design.space(body,24);Design.text(body,"Loading record…",15,400,Design.MUTED);}
    private void load(){Records.Factory factory=Records.factory;worker.execute(()->{try(Store store=factory.open(getApplicationContext())){RecordEntry found=Records.get(store,id);runOnUiThread(()->{if(isDestroyed())return;record=found;expectedUpdated=pending!=null?pending.getLong("expectedUpdated",record.updated):record.updated;zone=record.zone();draft=record.edit.copy();restoreDraft();render();});}catch(Exception e){runOnUiThread(()->{if(isDestroyed())return;LinearLayout body=Design.page(this,false,null,n->{});RecordUi.header(body,"Edit sleep",this::finish);Design.space(body,24);Design.text(body,"Record unavailable. "+e.getMessage(),15,400,Design.MUTED);Design.button(body,"Try again",true,this::load);});}});}
    private void restoreDraft(){if(pending==null||!pending.containsKey("start"))return;draft.start=pending.getLong("start");draft.end=pending.getLong("end");draft.note=pending.getString("note","");draft.rating=pending.getInt("rating");draft.rated=pending.getBoolean("rated");draft.tags.clear();draft.tags.addAll(pending.getStringArrayList("tags"));draft.awake.clear();long[] intervals=pending.getLongArray("awake");if(intervals!=null)for(int i=0;i+1<intervals.length;i+=2)draft.awake.add(new RecordIntervals.Span(intervals[i],intervals[i+1]));pending=null;}
    @Override public void onSaveInstanceState(Bundle state){super.onSaveInstanceState(state);if(draft==null)return;if(note!=null)draft.note=note.getText().toString();state.putString("createToken",createToken);state.putString("saveToken",saveToken);state.putLong("expectedUpdated",expectedUpdated);state.putLong("start",draft.start);state.putLong("end",draft.end);state.putString("note",draft.note);state.putInt("rating",draft.rating);state.putBoolean("rated",draft.rated);state.putStringArrayList("tags",new ArrayList<>(draft.tags));long[] spans=new long[draft.awake.size()*2];for(int n=0;n<draft.awake.size();n++){spans[n*2]=draft.awake.get(n).start;spans[n*2+1]=draft.awake.get(n).end;}state.putLongArray("awake",spans);}
    private void render(){LinearLayout body=Design.page(this,false,null,n->{});RecordUi.label(this,body);LinearLayout header=RecordUi.header(body,id==0?"Add sleep":"Edit sleep",this::finish);RecordUi.headerAction(header,"more","Record options",this::options);Design.space(body,4);date=Design.text(body,RecordUi.date(draft.end,zone),14,500,Design.MUTED);date.setPadding(Design.dp(this,40),0,0,0);Design.space(body,12);
        Design.text(body,id==0||record!=null&&record.manual()?"Sleep period":"Recorded period",14,600,Design.INK);timeline=new PeriodTimeline(this,record,draft,(a,b)->boundsChanged());body.addView(timeline,new LinearLayout.LayoutParams(-1,Design.dp(this,116)));Design.space(body,10);
        Design.text(body,"Duration",14,600,Design.INK);Design.space(body,4);duration=Design.text(body,"",39,700,Design.INK);Design.space(body,12);LinearLayout times=Design.row(this);LinearLayout start=periodButton(times,"moon","Start",()->chooseTime("Start",draft.start,value->{if(value>=draft.end)throw new IllegalArgumentException("Start must be before end.");if(record!=null&&!record.manual()&&value<record.rawStart)throw new IllegalArgumentException("Start must stay inside the original recording.");draft.start=value;boundsChanged();}));startValue=(TextView)start.getChildAt(1);LinearLayout end=periodButton(times,"sun","End",()->chooseTime("End",draft.end,value->{if(value<=draft.start)throw new IllegalArgumentException("End must be after start.");if(record!=null&&!record.manual()&&value>record.rawEnd)throw new IllegalArgumentException("End must stay inside the original recording.");if((record==null||record.manual())&&value>System.currentTimeMillis())throw new IllegalArgumentException("A completed manual record cannot end in the future.");draft.end=value;boundsChanged();}));endValue=(TextView)end.getChildAt(1);body.addView(times);
        Button addAwake=RecordUi.quietButton(body,"+   Add awake period",this::addAwake);addAwake.setText(RecordUi.withIcon(this,"Add awake period","plus",Design.BROWN));addAwake.setContentDescription("Add awake period");awake=Design.col(this);body.addView(awake);editorHeading(body,"Tags");tags=Design.col(this);body.addView(tags);drawTags();editorHeading(body,"Notes");note=new EditText(this);note.setText(draft.note);note.setHint("Add a note or dream");note.setHintTextColor(Design.MUTED);note.setTextColor(Design.INK);note.setTextSize(14*Appearance.scale(this));note.setTypeface(Design.font(this,400));note.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_FLAG_MULTI_LINE|InputType.TYPE_TEXT_FLAG_CAP_SENTENCES);note.setGravity(Gravity.TOP);note.setMinLines(1);note.setMaxLines(6);note.setBackground(Design.shape(this,Design.CREAM,12));android.graphics.drawable.GradientDrawable outline=Design.shape(this,Design.CREAM,12);outline.setStroke(Design.dp(this,1),Design.LINE);note.setBackground(outline);Design.pad(note,14,12);note.setContentDescription("Notes or dream");body.addView(note,new LinearLayout.LayoutParams(-1,-2));Design.space(body,12);
        Design.text(body,record==null?"User-reported period · no sensor measurements.":record.provenance()+(record.manual()?" · no sensor measurements.":" · original measurements are preserved."),11,400,Design.MUTED);if(record!=null&&record.zone.isEmpty()){Design.space(body,5);Design.text(body,"Original time zone unavailable; shown in "+zone.getId()+".",10,400,Design.MUTED);}error=Design.text(body,failure,12,500,0xffa9231d);error.setVisibility(failure.isEmpty()?View.GONE:View.VISIBLE);Design.space(body,10);
        LinearLayout footer=RecordUi.footer(body);save=Design.button(footer,saving?"Saving…":"Save changes",true,this::save);save.setEnabled(!saving);if(id!=0){Button delete=RecordUi.quietButton(footer,"Delete record",this::confirmDelete);delete.setText(RecordUi.withIcon(this,"Delete record","trash",0xffc62020));delete.setContentDescription("Delete record");delete.setTextColor(0xffc62020);delete.setBackground(Design.touch(this,android.graphics.Color.TRANSPARENT,12));delete.setEnabled(!saving);}updateValues();drawAwakes();if(saving&&resumed)observeSave();}
    private void editorHeading(LinearLayout body,String text){Design.space(body,12);Design.text(body,text,14,600,Design.INK);Design.space(body,4);}
    private LinearLayout periodButton(LinearLayout parent,String icon,String title,Runnable click){LinearLayout column=Design.col(this);Design.pad(column,12,10);android.graphics.drawable.GradientDrawable surface=Design.shape(this,Design.CREAM,12);surface.setStroke(Design.dp(this,1),Design.LINE);column.setBackground(surface);LinearLayout label=Design.row(this);Design.Icon glyph=new Design.Icon(this,icon,Design.BROWN);LinearLayout.LayoutParams gp=new LinearLayout.LayoutParams(Design.dp(this,22),Design.dp(this,22));gp.rightMargin=Design.dp(this,10);label.addView(glyph,gp);label.addView(Design.text(this,title,12,400,Design.MUTED));column.addView(label);Design.text(column,"",17,600,Design.INK).setPadding(Design.dp(this,32),Design.dp(this,4),0,0);((TextView)column.getChildAt(1)).setCompoundDrawables(null,null,RecordUi.glyph(this,"down",Design.INK,14),null);column.setMinimumHeight(Design.dp(this,66));column.setContentDescription("Change "+title.toLowerCase(Locale.ROOT)+" time");column.setOnClickListener(v->click.run());LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,-2,1);lp.setMargins(parent.getChildCount()==0?0:Design.dp(this,6),0,parent.getChildCount()==0?Design.dp(this,6):0,0);parent.addView(column,lp);return column;}
    private long effective(){if(draft.end<=draft.start)return 0;return record==null?RecordIntervals.length(RecordIntervals.subtract(List.of(new RecordIntervals.Span(draft.start,draft.end)),draft.awake)):record.draft(draft).duration();}
    private void updateValues(){date.setText(RecordUi.date(draft.end,zone));duration.setText(RecordUi.units(RecordUi.duration(effective())));startValue.setText(draft.end-draft.start<120000?RecordUi.preciseClock(this,draft.start,zone):RecordUi.clock(this,draft.start,zone));endValue.setText(draft.end-draft.start<120000?RecordUi.preciseClock(this,draft.end,zone):RecordUi.clock(this,draft.end,zone));}
    private void boundsChanged(){List<RecordIntervals.Span> trimmed=RecordIntervals.intersect(draft.awake,draft.start,draft.end);draft.awake.clear();draft.awake.addAll(trimmed);if(timeline!=null)timeline.changed();if(duration!=null)updateValues();if(awake!=null)drawAwakes();}
    private void drawTags(){tags.removeAllViews();RecordTagFlow flow=new RecordTagFlow(this);tags.addView(flow,new LinearLayout.LayoutParams(-1,-2));for(String tag:new ArrayList<>(draft.tags)){View chip=RecordUi.chip(this,tag+"  ×",false,()->{draft.tags.remove(tag);drawTags();});TextView face=(TextView)((FrameLayout)chip).getChildAt(0);android.graphics.drawable.GradientDrawable tagFace=Design.shape(this,0xffe9dcff,24);tagFace.setStroke(Design.dp(this,1),Design.VIOLET);face.setBackground(tagFace);face.setText(RecordUi.withIcon(this,tag+"  ×",tag.equalsIgnoreCase("Late meal")?"meal":tag.equalsIgnoreCase("Exercise")?"exercise":"tag",Design.INK));chip.setContentDescription("Remove tag "+tag);flow.addView(chip,new ViewGroup.LayoutParams(-2,Design.dp(this,48)));}View add=RecordUi.chip(this,"+  Add tag",false,this::addTag);add.setContentDescription("Add tag");flow.addView(add,new ViewGroup.LayoutParams(-2,Design.dp(this,48)));}
    private void addTag(){EditText input=new EditText(this);input.setSingleLine();input.setHint("Tag name");input.setContentDescription("Tag name");AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Add tag").setView(input).setPositiveButton("Add",null).setNegativeButton("Cancel",null).create();dialog.setOnShowListener(v->dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(w->{try{draft.addTag(input.getText().toString());drawTags();dialog.dismiss();}catch(IllegalArgumentException e){input.setError(e.getMessage());}}));dialog.show();ReportDialogs.style(dialog);}
    private void drawAwakes(){awake.removeAllViews();for(int i=0;i<draft.awake.size();i++){int index=i;RecordIntervals.Span span=draft.awake.get(i);LinearLayout row=Design.row(this);TextView label=Design.text(this,RecordUi.clock(this,span.start,zone)+" – "+RecordUi.clock(this,span.end,zone)+" · awake",12,400,Design.MUTED);row.addView(label,new LinearLayout.LayoutParams(0,-2,1));row.addView(Design.iconButton(this,"close","Remove awake period "+(i+1),()->{draft.awake.remove(index);updateValues();drawAwakes();timeline.changed();}),new LinearLayout.LayoutParams(Design.dp(this,48),Design.dp(this,48)));awake.addView(row);}}
    private void addAwake(){chooseTime("Awake starts",draft.start,start->chooseTime("Awake ends",Math.min(draft.end,start+10*60000L),end->{if(start<draft.start||end>draft.end||end<=start){showError("Keep awake periods inside this record, with end after start.");return;}draft.awake.add(new RecordIntervals.Span(start,end));updateValues();drawAwakes();timeline.changed();}));}
    private void options(){if(saving)return;List<String> options=new ArrayList<>();if(id!=0)options.add("View recorded signals");options.add("How rested did you feel?");if(record!=null&&!record.manual()&&record.edited)options.add("Restore original record");new AlertDialog.Builder(this).setTitle("Record options").setItems(options.toArray(new String[0]),(d,w)->{String choice=options.get(w);if(choice.equals("View recorded signals"))startActivity(RecordUi.intent(this,RecordSignalsActivity.class).putExtra("record",id));else if(choice.equals("Restore original record"))new AlertDialog.Builder(this).setTitle("Restore the original record?").setMessage("Discard saved trims, awake edits, tags and notes. Original measurements remain.").setPositiveButton("Restore original",(a,b)->reset()).setNegativeButton("Keep edits",null).show();else rating();}).show();}
    private void rating(){String[] labels={"Not rated","0 · Worst","1","2","3","4","5 · Best"};int checked=draft.rated?draft.rating+1:0;new AlertDialog.Builder(this).setTitle("How rested did you feel?").setSingleChoiceItems(labels,checked,(d,w)->{draft.rated=w>0;draft.rating=Math.max(0,w-1);d.dismiss();}).setNegativeButton("Cancel",null).show();}
    private void showError(String message){failure=message;if(error!=null){error.setText(message);error.setVisibility(View.VISIBLE);}Ui.toast(this,message);}
    private void save(){if(saving)return;draft.note=note.getText().toString();try{draft.validate(record==null?draft.start:record.rawStart,record==null?draft.end:record.rawEnd,record==null||record.manual(),System.currentTimeMillis());}catch(IllegalArgumentException e){showError(e.getMessage());return;}saving=true;saveToken=UUID.randomUUID().toString();save.setEnabled(false);save.setText("Saving…");observeSave();}
    private void observeSave(){if(!resumed||!saving||draft==null||saveToken==null)return;RecordSaves.Operation operation=RecordSaves.start(this,saveToken,createToken,id,draft,zone,expectedUpdated);if(!operation.done){handler.removeCallbacks(pollSave);handler.postDelayed(pollSave,100);return;}String token=saveToken;saveToken=null;saving=false;RecordSaves.forget(token);if(operation.error!=null){save.setEnabled(true);save.setText("Save changes");showError("Could not save. "+operation.error);return;}saving=false;setResult(RESULT_OK);if(isTaskRoot())startActivity(RecordUi.intent(this,HistoryActivity.class));finish();}
    private final Runnable pollSave=this::observeSave;
    @Override protected void onResume(){super.onResume();resumed=true;observeSave();}
    @Override protected void onPause(){resumed=false;handler.removeCallbacks(pollSave);super.onPause();}
    private void reset(){Records.Factory factory=Records.factory;worker.execute(()->{try(Store store=factory.open(getApplicationContext())){Records.reset(store,id,expectedUpdated);RecordEntry original=Records.get(store,id);runOnUiThread(()->{if(isDestroyed())return;record=original;expectedUpdated=original.updated;draft=record.edit.copy();failure="";render();});}catch(Exception e){runOnUiThread(()->{if(!isDestroyed())showError(e.getMessage());});}});}
    private void confirmDelete(){new AlertDialog.Builder(this).setTitle("Delete this record?").setMessage("Delete this period, its original sensor readings and its audio files. Other records and alarms remain.").setPositiveButton("Delete record",(d,w)->{if(saving)return;saving=true;Records.Factory factory=Records.factory;worker.execute(()->{try(Store store=factory.open(getApplicationContext())){List<String> paths=Records.delete(store,id,expectedUpdated);boolean failed=false;for(String path:paths){FileSafety.deleteClip(this,path);try{failed|=FileSafety.clip(this,path).exists();}catch(Exception bad){failed=true;}}boolean cleanupFailed=failed;runOnUiThread(()->{if(isDestroyed())return;if(cleanupFailed)Ui.toast(this,"Record deleted; some audio could not be removed from storage.");saving=false;setResult(RESULT_OK);if(isTaskRoot())startActivity(RecordUi.intent(this,HistoryActivity.class));finish();});}catch(Exception e){runOnUiThread(()->{if(!isDestroyed()){saving=false;showError("Could not delete. "+e.getMessage());}});}});}).setNegativeButton("Keep record",null).show();}
    private void chooseTime(String title,long initial,LongConsumer result){
        ZonedDateTime original=Instant.ofEpochMilli(initial).atZone(zone);LocalDateTime[] local={original.toLocalDateTime()};ZoneOffset[] chosen={original.getOffset()};LinearLayout form=Design.col(this);Design.pad(form,20,12);Button date=RecordUi.quietButton(form,"",()->{}),time=RecordUi.quietButton(form,"",()->{});TextView zoneLabel=Design.text(form,zone.getId(),12,400,Design.MUTED);RadioGroup offsets=new RadioGroup(this);form.addView(offsets);boolean seconds=draft.end-draft.start<120000;EditText second=null;if(seconds){Design.text(form,"Seconds",12,500,Design.INK);second=new EditText(this);second.setInputType(InputType.TYPE_CLASS_NUMBER);second.setText(""+original.getSecond());second.setContentDescription("Seconds");form.addView(second);}TextView warning=Design.text(form,"",12,500,0xffa9231d);
        Runnable refresh=()->{date.setText(local[0].toLocalDate().format(DateTimeFormatter.ofPattern("EEE d MMM uuuu",Locale.getDefault())));time.setText(local[0].toLocalTime().format(DateTimeFormatter.ofPattern(android.text.format.DateFormat.is24HourFormat(this)?"HH:mm":"h:mm a",Locale.getDefault())));offsets.removeAllViews();List<ZoneOffset> available=zone.getRules().getValidOffsets(local[0]);if(!available.contains(chosen[0]))chosen[0]=null;if(available.size()>1)for(int i=0;i<available.size();i++){ZoneOffset offset=available.get(i);RadioButton radio=new RadioButton(this);radio.setText((i==0?"Earlier":"Later")+" offset · UTC"+offset);radio.setMinHeight(Design.dp(this,48));radio.setChecked(offset.equals(chosen[0]));radio.setOnClickListener(v->chosen[0]=offset);offsets.addView(radio);}};
        date.setOnClickListener(v->new DatePickerDialog(this,(view,y,m,d)->{local[0]=LocalDateTime.of(LocalDate.of(y,m+1,d),local[0].toLocalTime());refresh.run();},local[0].getYear(),local[0].getMonthValue()-1,local[0].getDayOfMonth()).show());time.setOnClickListener(v->SleepPicker.time(this,title+" time",local[0].getHour()*60+local[0].getMinute(),minutes->{local[0]=local[0].withHour(minutes/60).withMinute(minutes%60);refresh.run();}));refresh.run();EditText secondField=second;
        AlertDialog dialog=new AlertDialog.Builder(this).setTitle(title).setView(form).setPositiveButton("Use time",null).setNegativeButton("Cancel",null).create();dialog.setOnShowListener(v->dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(w->{try{LocalDateTime value=local[0];if(secondField!=null){int sec=Integer.parseInt(secondField.getText().toString());if(sec<0||sec>59)throw new IllegalArgumentException("Seconds must be from 0 to 59.");value=value.withSecond(sec);}long instant=RecordDraft.instant(value,zone,chosen[0]);if(value.equals(original.toLocalDateTime())&&original.getOffset().equals(chosen[0]))instant=initial;result.accept(instant);dialog.dismiss();}catch(IllegalArgumentException e){warning.setText(e.getMessage());}}));dialog.show();
    }
    @Override public void finish(){if(saving){Ui.toast(this,"Please wait for this save to finish.");return;}super.finish();}
    // Android 11/12 fallback; Android 13+ uses the platform callback above.
    @android.annotation.SuppressLint("GestureBackNavigation")
    @Override public void onBackPressed(){if(saving){Ui.toast(this,"Please wait for this save to finish.");return;}super.onBackPressed();}
    @Override public void onWindowFocusChanged(boolean focused){super.onWindowFocusChanged(focused);if(focused)RecordUi.lightBars(this);}
    void awaitReaders(long timeoutMs)throws Exception {if(worker.isShutdown()){if(!worker.awaitTermination(timeoutMs,TimeUnit.MILLISECONDS))throw new TimeoutException("Record workers still active");}else worker.submit(()->{}).get(timeoutMs,TimeUnit.MILLISECONDS);}
    @Override protected void onDestroy(){handler.removeCallbacks(pollSave);worker.shutdown();super.onDestroy();}
}
